-- Modify "credit_attribution" table
ALTER TABLE "credit_attribution" DROP CONSTRAINT "credit_attribution_role_not_blank", ADD CONSTRAINT "credit_attribution_role_check" CHECK (role = ANY (ARRAY['author'::text, 'co-author'::text, 'translator'::text, 'illustrator'::text, 'editor'::text, 'publisher'::text, 'letterer'::text, 'colorist'::text, 'developer'::text, 'composer'::text, 'designer'::text, 'director'::text, 'producer'::text, 'writer'::text, 'actor'::text, 'narrator'::text, 'studio'::text, 'distributor'::text]));
-- Modify "subject_association" table
ALTER TABLE "subject_association" DROP CONSTRAINT "subject_association_role_not_blank", ADD CONSTRAINT "subject_association_role_check" CHECK (role = ANY (ARRAY['primary_character'::text, 'featured_character'::text, 'appears'::text, 'about'::text, 'setting'::text, 'source_work'::text, 'canonical_wiki_page'::text, 'related_subject'::text]));
-- Modify "unit_association_proposal" table
ALTER TABLE "unit_association_proposal" ADD CONSTRAINT "unit_association_proposal_role_check" CHECK (((kind = 'credit'::association_kind) AND (role = ANY (ARRAY['author'::text, 'co-author'::text, 'translator'::text, 'illustrator'::text, 'editor'::text, 'publisher'::text, 'letterer'::text, 'colorist'::text, 'developer'::text, 'composer'::text, 'designer'::text, 'director'::text, 'producer'::text, 'writer'::text, 'actor'::text, 'narrator'::text, 'studio'::text, 'distributor'::text]))) OR ((kind = 'subject'::association_kind) AND (role = ANY (ARRAY['primary_character'::text, 'featured_character'::text, 'appears'::text, 'about'::text, 'setting'::text, 'source_work'::text, 'canonical_wiki_page'::text, 'related_subject'::text]))));
